#define mii map<int, int>
#define ios ios::sync_with_stdio(0);cin.tie(0);cout.tie(0)
const int MOD = 1e9+7;

// functions are Written with routine coding tools
void moveDisk(int disk, int source, int destination) {
    cout << source << ' ' << destination << '\n';
}

void hanoi(int disks, int source, int auxiliary, int destination) {
    if (disks == 1) {
        moveDisk(disks, source, destination);
    } else {
        hanoi(disks - 1, source, destination, auxiliary);
        moveDisk(disks, source, destination);
        hanoi(disks - 1, auxiliary, source, destination);
    }
}

int32_t main() {

    ios;
    int n; cin >> n;
    cout << pow(2, n) - 1 << '\n';
    hanoi(n, 1, 2, 3);
    return 0;
}

/*
 * buffer_pool_manager.cpp
 *
 * Functionality: The simplified Buffer Manager interface allows a client to
 * new/delete pages on disk, to read a disk page into the buffer pool and pin
 * it, also to unpin a page in the buffer pool.
 */

#include "buffer/buffer_pool_manager.h"

namespace cmudb {

/*
 * BufferPoolManager Constructor
 * When log_manager is nullptr, logging is disabled (for test purpose)
 * WARNING: Do Not Edit This Function
 */
BufferPoolManager::BufferPoolManager(size_t pool_size,
                                     DiskManager *disk_manager,
                                     LogManager *log_manager)
    : pool_size_(pool_size), disk_manager_(disk_manager),
      log_manager_(log_manager) {

  // a consecutive memory space for buffer pool
  pages_ = new Page[pool_size_];
  free_list_ = new std::list<Page *>;

  replacer_ = new LRUReplacer<Page *>;
  page_table_ = new ExtendibleHash<page_id_t, Page *>(BUCKET_SIZE);

  // put all the pages into free list
  for (size_t i = 0; i < pool_size_; ++i) {
    free_list_->push_back(&pages_[i]);
  }
}

/*
 * BufferPoolManager Destructor
 * WARNING: Do Not Edit This Function
 */
BufferPoolManager::~BufferPoolManager() {
  delete[] pages_;
  delete page_table_;
  delete replacer_;
  delete free_list_;
}

/**
 * 1. search hash table.
 *  1.1 if exist, pin the page and return immediately
 *  1.2 if no exist, find a replacement entry from either free list or lru
 *      replacer. (NOTE: always find from free list first)
 * 2. If the entry chosen for replacement is dirty, write it back to disk.
 * 3. Delete the entry for the old page from the hash table and insert an
 * entry for the new page.
 * 4. Update page metadata, read page content from disk file and return page
 * pointer
 */
Page *BufferPoolManager::FetchPage(page_id_t page_id) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *res = nullptr;
  if (page_table_->Find(page_id, res)) {
    // mark the Page as pinned
    ++res->pin_count_;
    // remove its entry from LRUReplacer
    replacer_->Erase(res);
    return res;
  } else {
    if (!free_list_->empty()) {
      res = free_list_->front();
      free_list_->pop_front();
    } else {
      if (!replacer_->Victim(res)) {
        return nullptr;
      }
    }
  }

  assert(res->pin_count_ == 0);
  // dirty? write back
  if (res->is_dirty_) {
    if (ENABLE_LOGGING) {
      while (res->GetLSN() > log_manager_->GetPersistentLSN()) {
        std::promise<void> promise;
        log_manager_->WakeupFlushThread(&promise);
      }
    }
    disk_manager_->WritePage(res->page_id_, res->GetData());
  }
  // delete the entry for old page.
  page_table_->Remove(res->page_id_);

  // insert an entry for the new page.
  page_table_->Insert(page_id, res);

  // initial meta data
  res->page_id_ = page_id;
  res->is_dirty_ = false;
  res->pin_count_ = 1;
  disk_manager_->ReadPage(page_id, res->GetData());

  return res;
}

/*
 * Implementation of unpin page
 * if pin_count>0, decrement it and if it becomes zero, put it back to
 * replacer if pin_count<=0 before this call, return false. is_dirty: set the
 * dirty flag of this page
 */
bool BufferPoolManager::UnpinPage(page_id_t page_id, bool is_dirty) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *page;
  if (page_table_->Find(page_id, page)) {
    if (page->pin_count_ <= 0) {
      return false;
    }
    if (--page->pin_count_ == 0) {
      replacer_->Insert(page);
    }
    if (is_dirty) {
      page->is_dirty_ = true;
    }
    return true;
  }
  return false;
}

/*
 * Used to flush a particular page of the buffer pool to disk. Should call the
 * write_page method of the disk manager
 * if page is not found in page table, return false
 * NOTE: make sure page_id != INVALID_PAGE_ID
 */
bool BufferPoolManager::FlushPage(page_id_t page_id) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *page;
  if (page_table_->Find(page_id, page)) {
    disk_manager_->WritePage(page_id, page->GetData());
    return true;
  }
  return false;
}

/**
 * User should call this method for deleting a page. This routine will call
 * disk manager to deallocate the page. First, if page is found within page
 * table, buffer pool manager should be responsible for removing this entry out
 * of page table, resetting page metadata and adding back to free list. Second,
 * call disk manager's DeallocatePage() method to delete from disk file. If
 * the page is found within page table, but pin_count != 0, return false
 */
bool BufferPoolManager::DeletePage(page_id_t page_id) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *page;
  if (page_table_->Find(page_id, page) && page->pin_count_ == 0) {
    page_table_->Remove(page_id);
    replacer_->Erase(page);
    disk_manager_->DeallocatePage(page_id);

    page->page_id_ = INVALID_PAGE_ID;
    page->is_dirty_ = false;
    free_list_->push_back(page);
  }
  return false;
}

/**
 * User should call this method if needs to create a new page. This routine
 * will call disk manager to allocate a page.
 * Buffer pool manager should be responsible to choose a victim page either
 * from free list or lru replacer(NOTE: always choose from free list first),
 * update new page's metadata, zero out memory and add corresponding entry
 * into page table. return nullptr if all the pages in pool are pinned
 */
Page *BufferPoolManager::NewPage(page_id_t &page_id) {
  std::lock_guard<std::mutex> lock(latch_);

  Page *res = nullptr;
  if (!free_list_->empty()) {
    res = free_list_->front();
    free_list_->pop_front();
  } else {
    if (!replacer_->Victim(res)) {
      return nullptr;
    }
  }

  assert(res->pin_count_ == 0);
  page_id = disk_manager_->AllocatePage();

  // dirty? write back
  if (res->is_dirty_) {
    if (ENABLE_LOGGING) {
      while (res->GetLSN() > log_manager_->GetPersistentLSN()) {
        std::promise<void> promise;
        log_manager_->WakeupFlushThread(&promise);
      }
    }
    disk_manager_->WritePage(res->page_id_, res->GetData());
  }
  // delete the entry for old page.
  page_table_->Remove(res->page_id_);

  // insert an entry for the new page.
  page_table_->Insert(page_id, res);

  // initial meta data
  res->page_id_ = page_id;
  res->is_dirty_ = false;
  res->pin_count_ = 1;
  res->ResetMemory();

  return res;
}

