LRESULT CALLBACK NostalgiaWindowProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static HWND hTextBox;
    static HWND hExecuteButton;
    static HWND hClearButton;
    static HWND hConsoleButton;
