using namespace std;

//̵߳ĳʼ--ʼִ
void MyPrint()
{
	cout << "߳̿ʼִ1\n" << endl;

	cout << "ִ߳2\n" << endl;
	cout << "ִ߳3\n" << endl;
	cout << "ִ߳4\n" << endl;
	cout << "ִ߳5\n" << endl;
	cout << "ִ߳6\n" << endl;

}

int main(void)
{
	//ʵִ߳(Զ߳)߳main()أִ



	//߳main()еĲ
	thread my_thread(MyPrint);//1̵̣߳߳㣨ڣMyPrint2MyPrint־߳ѾʼִУ̺߳MyPrintִ 
	//An application-defined function to be executed by the thread.
	//߳ȴִ߳ϣȻ̺̻߳߳ϣȻ߳ټִС
	//my_thread.join();//ֱִBlocks until the associated thread completes.
	if (my_thread.joinable())
	{
		cout << "can join" << endl;
	}
	else
	{
		cout << "can not join" << endl;
	}
	my_thread.detach();

	if (my_thread.joinable())
	{
		cout << "2can join" << endl;
	}
	else
	{
		cout << "2can not join" << endl;
	}
	//߳ȴMyPrintִϣִ߳ϣͽִ̼߳
	//ȥһִ̺߳߳̽Уң߳Ƚʱ߳̿δִϣᱻϵͳɱ
	//һдõĳӦ̵߳ȴִ߳ϺԼܽ

	//joinable()жʱʹjoindetach  --Specifies whether the associated thread is joinable.truefalse



	/*
	 *Լһ̴̣߳߳main()ʼִУԼ߳ҲҪһʼִ
	 *ʼ--һִϣʹ߳̽
	 *
	 *Ƿִϵı־߳Ƿִϣִ߳ϣʹ̽
	 *ʱ߳ûִϣôЩ߳Ҳᱻϵͳǿֹ
	 *һǵõһۣҪ뱣֤̣߳Լô봴̣߳״̬Ҫ߳һֱУ
	 *Ҫ߳
	 *ѧϰĿǰ伴ɡ
	 *
	 *ôд̳߳
	 *	1ͷļthread  #include <thread>
	 *	 (2)һΪ߳̿ʼִеĵط--ʼ
	 *	 3main()д룬һ߳
	 *	 4ӺĴִϣ߳˳
	 *ڱ߳ܣ൱ͬʱܣͬʱ
	 *ʹһ߱סˣһ߻ǿͨеġ
	 *
	 */

	/*
	 * ߳ǲǿԲȴִ߳ϣԼȽdetache()Detaches the associated thread from the thread object.
	 The operating system becomes responsible for releasing thread resources on termination.
	 * ͳĶ̳߳߳Ҫȴִ߳ϣȻԼ˳ʹdetach̷ִ̺߳߳С
	 * detach()ᵼ߳ʧȥԼĿơһdetach()߳̾ͱϵͳӹܣͲʹjoin()쳣
	 * 
	 * 
	 * Ϊʲôdetach()
	 *  1Ǵ˺̣ܶ߳߳һһȴ߳̽detach()
