DWORD WINAPI ThreadProc(LPVOID lpParam){
	BYTE b[1030];
	DWORD d = 0;
	while (ReadFile((HANDLE)lpParam, b, 1024, &d, 0))
	{
		b[d] = '\0';
		printf("%s", b);
		fflush(stdout);
	}
	return 0;
}
void die(char* c)
{
	printf("%s: %d\n", c, GetLastError());
	exit(-1);
}
