	STARTUPINFO si = {};
	si.cb = sizeof(si);
	si.hStdInput = GetCurrentThread();
	si.hStdOutput = GetCurrentThread();
	si.hStdError = GetCurrentThread();
	si.wShowWindow = SW_HIDE;
	si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
