//-----------------------------------------------------------------------------
// Purpose: 
//
//
//-----------------------------------------------------------------------------
void CNPC_Combine::Spawn( void )
{
	SetHullType(HULL_HUMAN);
	SetHullSizeNormal();

	SetSolid( SOLID_BBOX );
	AddSolidFlags( FSOLID_NOT_STANDABLE );
	SetMoveType( MOVETYPE_STEP );
	SetBloodColor( BLOOD_COLOR_RED );
	m_flFieldOfView			= -0.2;// indicates the width of this NPC's forward view cone ( as a dotproduct result )
	m_NPCState				= NPC_STATE_NONE;
	m_flNextGrenadeCheck	= gpGlobals->curtime + 1;
	m_flNextPainSoundTime	= 0;
	m_flNextAlertSoundTime	= 0;
	m_bShouldPatrol			= false;

	//	CapabilitiesAdd( bits_CAP_TURN_HEAD | bits_CAP_MOVE_GROUND | bits_CAP_MOVE_JUMP | bits_CAP_MOVE_CLIMB);
	// JAY: Disabled jump for now - hard to compare to HL1
	CapabilitiesAdd( bits_CAP_TURN_HEAD | bits_CAP_MOVE_GROUND );

	CapabilitiesAdd( bits_CAP_AIM_GUN );

	// Innate range attack for grenade
	// CapabilitiesAdd(bits_CAP_INNATE_RANGE_ATTACK2 );

	// Innate range attack for kicking
	CapabilitiesAdd(bits_CAP_INNATE_MELEE_ATTACK1 );

	// Can be in a squad
	CapabilitiesAdd( bits_CAP_SQUAD);
	CapabilitiesAdd( bits_CAP_USE_WEAPONS );

	CapabilitiesAdd( bits_CAP_DUCK );				// In reloading and cover

	CapabilitiesAdd( bits_CAP_NO_HIT_SQUADMATES );
	CapabilitiesAdd(bits_CAP_FRIENDLY_DMG_IMMUNE); // Prevent friendly fire from allies

	string_t weapon_remington870 = AllocPooledString("weapon_remington870");

	if (npc_combine_allow_climbing.GetBool())
	{
		CapabilitiesAdd(bits_CAP_MOVE_CLIMB);
	}

	// me trying to add stupid shit be like
	if (IsElite())
	{
		if (npc_combine_elites_always_spawn_with_ar2.GetBool())
		{
			m_iTacticalVariant = TACTICAL_VARIANT_PRESSURE_ENEMY;
			m_spawnEquipment = AllocPooledString("weapon_ar2");
		}
	}
	else if (IsCharger())
	{
		// "Ready to hammer in three... two... one..."
		CapabilitiesRemove(bits_CAP_DUCK);
		m_iTacticalVariant = TACTICAL_VARIANT_PRESSURE_ENEMY;
		m_spawnEquipment = AllocPooledString("weapon_ar2");
	}
	else if (IsSuppressor())
	{
		// "Antibody Protection Force active on."
		CapabilitiesRemove(bits_CAP_DUCK);
		CapabilitiesRemove(bits_CAP_INNATE_MELEE_ATTACK1);
		m_iTacticalVariant = TACTICAL_VARIANT_DEFAULT;
		m_spawnEquipment = AllocPooledString("weapon_ar2");
	}
	else if (IsShield())
	{
		CapabilitiesRemove(bits_CAP_DUCK);
		CapabilitiesRemove(bits_CAP_INNATE_MELEE_ATTACK1);
		m_iTacticalVariant = TACTICAL_VARIANT_DEFAULT;
		if (random->RandomFloat() < sk_npc_pistol_chance.GetFloat())
		{
			m_spawnEquipment = AllocPooledString("weapon_glock18");
		}
		else
		{
			m_spawnEquipment = AllocPooledString("weapon_pistol");
		}
	}
	else
	{
		// 25% chance to equip the MP5
		if (m_spawnEquipment == gm_isz_class_SMG1 && random->RandomFloat() < sk_npc_smg_chance.GetFloat())
		{
			m_spawnEquipment = AllocPooledString("weapon_mp5");
		}

		// 25% chance to equip the Remington 870
		if (m_spawnEquipment == gm_isz_class_Shotgun && random->RandomFloat() < sk_npc_shotgun_chance.GetFloat())
		{
			m_spawnEquipment = weapon_remington870;
		}
	}

	m_bFirstEncounter	= true;// this is true when the grunt spawns, because he hasn't encountered an enemy yet.

	m_HackedGunPos = Vector (npc_combine_hacked_gunpos_position_posX.GetInt(), npc_combine_hacked_gunpos_position_posY.GetInt(), npc_combine_hacked_gunpos_position_posZ.GetInt() );

	m_flStopMoveShootTime = FLT_MAX; // Move and shoot defaults on.
	m_MoveAndShootOverlay.SetInitialDelay( npc_combine_move_and_shoot_delay.GetFloat() ); // But with a bit of a delay.

	m_flNextLostSoundTime		= 0;
	m_flAlertPatrolTime			= 0;

	m_flNextAltFireTime = gpGlobals->curtime;

	NPCInit();

#ifdef MAPBASE
	// This was moved from CalcWeaponProficiency() so soldiers don't change skin unnaturally and uncontrollably
	if ( GetActiveWeapon() )
	{
		// Have to move this here, to support both vanilla shotgun and remington 870
		bool isShotgunner = EntIsClass(GetActiveWeapon(), gm_isz_class_Shotgun) || EntIsClass(GetActiveWeapon(), weapon_remington870);
		if (isShotgunner && m_nSkin != COMBINE_SKIN_SHOTGUNNER)
		{
			m_nSkin = COMBINE_SKIN_SHOTGUNNER;
		}
	}
#endif
}

